import {branch as branchHOC, renderNothing} from 'recompose'

import compose from 'lodash/flowRight'
import * as React from 'react'
import {connect} from 'react-redux'

import type {State} from '../../../reducers/types'
import {getBuild} from '../../../selectors'

import BuildApproval from './BuildApproval'
import type {OwnProps, Props, StateProps} from './BuildApproval.types'

const mapStateToProps = (state: State, {buildId}: OwnProps): StateProps => {
  const shouldRender = !!getBuild(state, buildId)?.approvalInfo

  return {
    shouldRender,
  }
}

export default compose(
  connect(mapStateToProps),
  React.memo,
  branchHOC((props: Props) => !props.shouldRender, renderNothing),
)(BuildApproval) as React.ComponentType<OwnProps>
