import batchVisible from '../../../actions/batchVisible'
import {buildDetailsQueue} from '../../../actions/buildDetailsQueue'
import {receiveCompatibleAgents} from '../../../actions/builds'
import type {AppThunk} from '../../../actions/types'
import {fetchQueryOnce} from '../../../relay/fetchQueryOnce'
import getEnvironment from '../../../relay/getEnvironment'
import type {BuildId} from '../../../types'
import {Namespace} from '../../../utils/namespace'

import type {CompatibleAgentsQuery} from './__generated__/CompatibleAgentsQuery.graphql'
import {compatibleAgentsQuery} from './CompatibleAgents.queries'

export const fetchCompatibleAgentsQueue: (id: BuildId) => AppThunk<void> = batchVisible({
  queue: buildDetailsQueue,
  namespace: Namespace.AGENTS,
  request: id =>
    fetchQueryOnce<CompatibleAgentsQuery>(getEnvironment(), compatibleAgentsQuery, {
      buildLocator: `id:${id}`,
    }).then(data =>
      data?.build != null
        ? [
            {
              ...data.build,
              id: data.build.id,
            },
          ]
        : [],
    ),
  action: receiveCompatibleAgents,
})
